export const getListEapEvidencesUrl = (id: string,
    params?: ListEapEvidencesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/projects/${id}/evidences?${stringifiedParams}` : `/projects/${id}/evidences`
}

